// port_test.cpp - headless checks that the C++ worlds match the JavaScript version.
// The expected numbers were taken by running js/tracks.js, js/city.js and the Miami section
// of js/game.js in Node. If a check fails, the port has drifted from the web game.
#include "game/city.h"
#include "game/miami.h"
#include "game/tracks.h"
#include <cstdio>
#include <string>

static int failures = 0;
static void Check(bool ok, const char* what) {
    std::printf("%s  %s\n", ok ? "ok  " : "FAIL", what);
    if (!ok) failures++;
}
static bool Near(double a, double b, double eps) { return std::fabs(a - b) <= eps; }

int main() {
    // stage: N, L, zones, clips, pass, limit, start x, start y
    struct Ref { int N; double L; int zones, clips, pass, limit; double sx, sy; };
    const Ref refs[] = {
        {472, 8489.929, 4, 7, 5200, 63, 1483.370, 433.603},
        {673, 12111.928, 5, 8, 6400, 84, 1616.268, 280.350},
        {665, 11975.641, 6, 9, 8200, 80, 1546.382, 379.236},
        {433, 7794.974, 4, 4, 4700, 50, 1193.008, 1031.207},
        {597, 10750.671, 3, 16, 10500, 67, 2838.305, 2461.275},
        {709, 12769.600, 5, 13, 10600, 77, 1160.700, 367.227},
        {673, 12106.587, 5, 8, 8100, 81, 1668.620, 421.915},
        {686, 12355.688, 5, 7, 8000, 95, 664.332, 2712.603},
        {1067, 19198.908, 7, 12, 12400, 128, 1585.260, 353.667},
        {587, 10562.561, 8, 9, 11600, 68, 225.041, 1657.361},
        {594, 10690.422, 6, 11, 11500, 63, 1854.666, 345.312},
        {602, 10840.995, 7, 11, 12400, 62, 1237.976, 2971.851},
    };
    for (size_t i = 0; i < STAGES.size(); i++) {
        Track T = BuildTrack(STAGES[i]);
        StageGoals(T, (int)i);
        int clips = 0;
        for (auto& z : T.zones) clips += (int)z.clips.size();
        const Ref& r = refs[i];
        bool ok = T.N == r.N && Near(T.L, r.L, 0.01) && (int)T.zones.size() == r.zones && clips == r.clips &&
                  T.pass == r.pass && T.limit == r.limit && Near(T.pts[0].x, r.sx, 0.01) && Near(T.pts[0].y, r.sy, 0.01);
        if (!ok) std::printf("      got N %d L %.3f zones %d clips %d pass %d limit %d start %.3f %.3f\n",
                             T.N, T.L, (int)T.zones.size(), clips, T.pass, T.limit, T.pts[0].x, T.pts[0].y);
        Check(ok, ("track " + STAGES[i].name).c_str());
    }

    EndlessCity city;
    RoadSpot s = city.Start();
    Check(Near(s.x, 104.0655, 1e-3) && Near(s.y, -4.5644, 1e-3) && Near(s.a, -0.049482, 1e-5), "city start");
    const char* surf = "";
    std::string got;
    for (int y = -3000; y <= 3000; y += 97)
        for (int x = -3000; x <= 3000; x += 89) got += (char)('0' + city.SurfaceAt(x, y));
    int diff = 0;
    for (size_t i = 0; i < got.size(); i++) diff += got[i] != surf[i];
    if (diff) std::printf("      %d of %zu surface samples differ\n", diff, got.size());
    Check(got.size() == std::string(surf).size() && diff == 0, "city surfaces on a 6000 px grid");
    // cells i, j, roads, solids, scenery, lots
    const int cells[][6] = {{0,0,2,0,18,0}, {1,0,4,5,20,1}, {-2,3,2,8,16,3}, {5,-4,1,0,12,0}, {7,7,3,6,21,2}};
    for (auto& c : cells) {
        CityCell* C = city.GetCell(c[0], c[1]);
        bool ok = (int)C->roads.size() == c[2] && (int)C->solids.size() == c[3] && (int)C->scenery.size() == c[4] && (int)C->lots.size() == c[5];
        if (!ok) std::printf("      got roads %zu solids %zu scenery %zu lots %zu\n", C->roads.size(), C->solids.size(), C->scenery.size(), C->lots.size());
        Check(ok, ("city cell " + std::to_string(c[0]) + "," + std::to_string(c[1])).c_str());
    }

    Miami m;
    m.Generate();
    double cs = 0;
    for (auto& sc : m.scenery) cs += sc.cx * 0.001 + sc.r + sc.ht * 100;
    long long ms = 0;
    for (size_t i = 0; i < m.map.size(); i++) ms += m.map[i] * (long long)(i % 7 + 1);
    bool ok = m.buildings.size() == 55 && m.scenery.size() == 314 && m.solids.size() == 187 && Near(cs, 11037.152874, 1e-4) && ms == 26137;
    if (!ok) std::printf("      got buildings %zu scenery %zu solids %zu checksum %.6f mapsum %lld\n", m.buildings.size(), m.scenery.size(), m.solids.size(), cs, ms);
    Check(ok, "Miami map, buildings and scenery");

    std::printf(failures ? "\n%d check(s) failed\n" : "\nall checks passed\n", failures);
    return failures ? 1 : 0;
}
